// ==================== src/audio.js ====================
{
let bgm = null;      
let sheepAud = null; 
let sheepTO = null;

function log$audio(s) { $$util('#log').textContent = s; }


function audioStart$audio() {
  if (S$state.muted) return;
  try {
    if (!S$state.actx) S$state.actx = new (window.AudioContext || window.webkitAudioContext)();
    S$state.actx.resume();
    if (!S$state.bgmOn) {
      S$state.bgmOn = true;
      if (bgm && !S$state.muted) bgm.play().catch(() => {});
    }
  } catch (e) {}
}

function tone$audio(f, d = .12, type = 'square', v = .03, slide = 0) {
  if (S$state.muted || !S$state.actx) return;
  const o = S$state.actx.createOscillator(), g = S$state.actx.createGain();
  o.type = type; o.frequency.value = f;
  if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, f + slide), S$state.actx.currentTime + d);
  g.gain.setValueAtTime(v, S$state.actx.currentTime);
  g.gain.exponentialRampToValueAtTime(.001, S$state.actx.currentTime + d);
  o.connect(g); g.connect(S$state.actx.destination);
  o.start(); o.stop(S$state.actx.currentTime + d);
}

function sfx$audio(a) {
  if (S$state.muted) return;
  if (a === 'hit') { tone$au(160, .15, 'sawtooth', .06, -90); tone$au(90, .2, 'square', .03, -40); }
  if (a === 'heal') [523, 659, 784, 1047].forEach((f, i) => setTimeout(() => tone$au(f, .15, 'sine', .04), i * 80));
  if (a === 'coin') tone$au(900, .12, 'square', .04, 350);
  if (a === 'hurt') tone$au(180, .25, 'sawtooth', .06, -120);
  if (a === 'win') [392, 523, 659, 784, 1047].forEach((f, i) => setTimeout(() => tone$au(f, .22, 'square', .035), i * 110));
}

function bgmPause$audio() { if (bgm) bgm.pause(); }
function bgmMuted$audio(m) { if (bgm) { bgm.muted = m; if (!m) bgm.play().catch(() => {}); } }


function tryList(list, ok) {
  let i = 0;
  (function nx() {
    if (i >= list.length) return;
    const a = new Audio();
    a.preload = 'auto';
    a.oncanplaythrough = () => { a.oncanplaythrough = null; ok(a, list[i - 1]); };
    a.onerror = () => nx();
    a.src = list[i++];
  })();
}

function setBgm(a) {
  if (bgm) bgm.pause();
  bgm = a; a.loop = true; a.volume = .6; a.muted = S$state.muted;
  if (S$state.mode === 'battle' || S$state.mode === 'dodge') a.play().catch(() => {});
}

function setSheep(a) { sheepAud = a; a.volume = 1; }

function loadRemoteAudio$audio() {
  tryList(BGM_SRC$data, setBgm);
  tryList(SHEEP_SRC$data, setSheep);
}


function sheepBeep$audio() {
  S$state.sheepSay = 2200;
  zoomFx$fx(0);
  if (S$state.muted) return;
  audioStart$au();
  if (sheepAud) {
    sheepAud.currentTime = 0;
    sheepAud.play().catch(() => {});
    clearTimeout(sheepTO);
    sheepTO = setTimeout(() => sheepAud.pause(), 2300);
    return;
  }
  try {
    speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance('beep beep, I’m a sheep');
    u.pitch = 2; u.rate = 1.4;
    speechSynthesis.speak(u);
  } catch (e) {}
}
}

