{
$$util('#tk').textContent = '📺 NEWS SNAPSHOT (Oct 20, 2026, not live): ' + NEWS$data.join('  🏳️‍🌈  ') + '  🏳️‍🌈  ';

function loop(now) {
  const dt = Math.min(40, now - (S$state.last || now));
  S$state.last = now;
  
  
  requestAnimationFrame(loop);
  fitGame$glfx(); 
  update$game(dt);
  x$draw.save();
  if (S$state.shake > 0) { x$draw.translate((Math.random() * 2 - 1) * S$state.shake, (Math.random() * 2 - 1) * S$state.shake); S$state.shake *= .86; }
  draw$draw();
  x$draw.restore();
  renderFX$glfx();
}

bindControls$game();
loadRemoteAudio$audio();
updateUI$game();
requestAnimationFrame(loop);
}
